import io,gzip,base64,zipfile,math
import pandas as pd
import numpy as np
import streamlit as st

st.set_page_config(page_title="V6.18 Pair Rakip Ayırıcı",page_icon="⚔️",layout="wide")
st.title("⚔️ V6.18 — GERÇEK PAIR vs RAKİP PAIR AYIRICI PROFESÖR")
st.success("KAPSAM KİLİTLİ: hareket tahmini doğru olan 152 ateşleme çekilişi / 12.008 pair satırı.")
st.caption("Her çekilişte oluşan exact ardışık çiftleri, aynı çekilişte oluşmayan 78/79 rakip çiftle karşılaştırır. Test çekilişinin H sonucu skora girmez.")

DATA=""""""

def load():
    return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA))))

d=load().sort_values(["draw_no","pair"]).reset_index(drop=True)
if d.draw_no.nunique()!=152 or len(d)!=12008:
    st.error(f"KAPSAM HATASI: {d.draw_no.nunique()} çekiliş / {len(d)} satır"); st.stop()

d["y"]=pd.to_numeric(d["target_full11"],errors="coerce").fillna(0).astype(int)

def bucket(v, cuts):
    try: x=float(v)
    except: return "NA"
    for name,lo,hi in cuts:
        if lo<=x<=hi:return name
    return "OTHER"

d["pre_blocks_bin"]=d["pre_total_blocks"].map(lambda x: bucket(x,[("B0_2",-99,2),("B3_4",3,4),("B5P",5,99)]))
d["bc_delta21_bin"]=d["block_count_delta_21"].map(lambda x: bucket(x,[("D2M",-99,-2),("D1",-1,-1),("D0",0,0),("U1",1,1),("U2P",2,99)]))
d["ml_delta21_bin"]=d["max_len_delta_21"].map(lambda x: bucket(x,[("D2M",-99,-2),("D1",-1,-1),("D0",0,0),("U1",1,1),("U2P",2,99)]))

# pair location descriptors, PRE-known and identity-based
def parse_pair(s):
    a,b=str(s).split("-")
    return int(a),int(b)
ab=d["pair"].map(parse_pair)
d["pair_a"]=[x[0] for x in ab]
d["pair_band"]=(d["pair_a"]//10).astype(int)
d["pair_lastdigit"]=d["pair_a"]%10

CAT=[
 "state_path","H1_state","H2_state","H3_state",
 "corridor_silent_H3_H1","same_pair_seen_11_same_day","Q2_GATE_FROZEN",
 "zone800","osc800","pre_blocks_bin","bc_delta21_bin","ml_delta21_bin",
 "pair_band","pair_lastdigit"
]

def smoothed_loglift(train, feature):
    base=(train.y.sum()+2)/(len(train)+8)
    g=train.groupby(feature,dropna=False).y.agg(["count","sum"]).reset_index()
    g["rate"]=(g["sum"]+2)/(g["count"]+8)
    g["loglift"]=np.log((g["rate"]+1e-9)/(base+1e-9))
    # reliability shrinkage; tiny groups contribute little
    g["w"]=g["count"]/(g["count"]+40.0)
    g["contrib"]=g["loglift"]*g["w"]
    return g[[feature,"contrib"]]

draws=sorted(d.draw_no.unique())
warmup=50
pred_rows=[]
audit=[]

for pos in range(warmup,len(draws)):
    target=draws[pos]
    tr=d[d.draw_no<target].copy()
    te=d[d.draw_no==target].copy()

    # baseline prior from historical pair outcomes only
    base=(tr.y.sum()+2)/(len(tr)+8)
    te["score"]=math.log(base/(1-base))

    # Feature-vs-competitor evidence learned only from past
    for f in CAT:
        tab=smoothed_loglift(tr,f)
        te=te.merge(tab,on=f,how="left")
        te["score"] += te["contrib"].fillna(0)
        te.drop(columns=["contrib"],inplace=True)

    # weak pair-specific history, strongly shrunk
    gp=tr.groupby("pair").y.agg(["count","sum"]).reset_index()
    gp["pair_rate"]=(gp["sum"]+2)/(gp["count"]+8)
    gp["pair_w"]=gp["count"]/(gp["count"]+120.0)
    gp["pair_extra"]=np.log((gp["pair_rate"]+1e-9)/(base+1e-9))*gp["pair_w"]
    te=te.merge(gp[["pair","pair_extra"]],on="pair",how="left")
    te["score"] += te["pair_extra"].fillna(0)

    te=te.sort_values(["score","pair"],ascending=[False,True]).reset_index(drop=True)
    actual_total=int(te.y.sum())

    for k in [1,2,3,4,5,8,10]:
        s=te.head(k)
        hits=int(s.y.sum())
        pred_rows.append({
            "draw_no":int(target),"K":k,"predicted_pairs":len(s),"exact_pair_hits":hits,
            "actual_pairs_in_draw":actual_total,"at_least_one":int(hits>0),
            "recall":hits/actual_total if actual_total else np.nan
        })

    for rank,(_,r) in enumerate(te.head(10).iterrows(),1):
        audit.append({
            "draw_no":int(target),"date":r["date"],"time":r["time"],"rank":rank,
            "pair":r["pair"],"score":float(r["score"]),"actual_hit":int(r["y"]),
            "state_path":r["state_path"],"H1_state":r["H1_state"]
        })

res=pd.DataFrame(pred_rows)
detail=pd.DataFrame(audit)
summary=(res.groupby("K").agg(
    test_draws=("draw_no","count"),
    predicted_pairs=("predicted_pairs","sum"),
    exact_pair_hits=("exact_pair_hits","sum"),
    actual_pairs=("actual_pairs_in_draw","sum"),
    draws_with_hit=("at_least_one","sum")
).reset_index())
summary["precision"]=summary.exact_pair_hits/summary.predicted_pairs
summary["recall"]=summary.exact_pair_hits/summary.actual_pairs
summary["draw_hit_rate"]=summary.draws_with_hit/summary.test_draws

st.metric("Kronolojik kör test",f"{len(draws)-warmup} çekiliş")
st.dataframe(summary,use_container_width=True,hide_index=True)

st.subheader("İlk 10 pair — olay olay")
st.dataframe(detail,use_container_width=True,hide_index=True)

st.warning("Bu sürüm eşik aramaz; sabit hiyerarşik feature-lift skoru kullanır. Sonuç iyi görünse bile yeni kural dondurulmadan önce ayrı ileri doğrulama gerekir.")

bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
    z.writestr("00_MANIFEST.txt","V6.18 PAIR vs RAKIP AYIRICI\n152 correct-movement draws. First 50 warmup, next 102 chronological blind. All ranking evidence from PRE-H history only.\n")
    z.writestr("01_WALK_FORWARD.csv",res.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("02_SUMMARY.csv",summary.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("03_TOP10_DETAIL.csv",detail.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.18 TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_18_PAIR_RAKIP_AYIRICI.zip","application/zip",use_container_width=True)
